window.MGProseData("38b98beaed26bf94c747aa3b2acdedf218121eb4f2f544a0a1594c3f83548953",{"html":"\u003cp>记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmunderover>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>r\u003c/mi>\u003c/munderover>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>2.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nk=\\sum_{i=1}^r\\binom{n_i}{2},\\qquad\ne_F=1,\\quad e_{K_{-1}}=e_{K_2}=2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对每块定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmstyle scriptlevel=\"1\">\u003cmtable rowspacing=\"0.1em\" columnalign=\"center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"1\" displaystyle=\"false\">\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003c/munder>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>χ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmtext>否则\u003c/mtext>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(1)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\delta_i=\n\\sum_{\\substack{a\\notin I_i\\\\ b\\in I_i}}\n\\frac{(A_i)_{ab}}2\\pmod2\\in\\mathbb F_2,\n\\qquad\n\\chi=\n\\begin{cases}\n1,\u0026amp;\\delta_1=\\cdots=\\delta_r=0,\\\\\n0,\u0026amp;\\text{否则}.\n\\end{cases}                                                   \\tag{1}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这些商均有意义，且只用到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\\bmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>全部三个域上的可行性判准相同：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>χ\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1.\u003c/mn>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(2)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad \\mathscr S_L(A)\\ne\\varnothing\\iff\\chi=1.\\quad}       \\tag{2}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n精确基数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left right left\" columnspacing=\"0em 1em 0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmi>χ\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">∣\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmi>χ\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmtext> \u003c/mtext>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>d\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(3)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n\\begin{aligned}\n|\\mathscr R_{L,M}(A)|\n   \u0026amp;=\\chi\\,2^{\\,e_Lk(M-1)+r} \u0026amp;\u0026amp;(M\\ge2),\\\\\n|\\mathscr C_{L,2}(A)|\n   \u0026amp;=2^{\\,e_L(k+d)},\\\\\n|\\mathscr C_{L,M}(A)|\n   \u0026amp;=\\chi\\,2^{\\,e_Lk(M-1)+e_Ld+r} \u0026amp;\u0026amp;(M\\ge3).\n\\end{aligned}}                                                \\tag{3}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,2}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 总非空；其余各集合的空性由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>χ\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\chi\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 完全决定。\u003c/p>\n\u003cp>对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar U\\in\\mathscr C_{L,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，任取逐条目提升 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\\in M_d(\\mathcal O_L)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>V\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>V\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(4)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n\\bar U\\in\\mathscr R_{L,M}(A)\n\\iff\n(V^{\\mathsf T}V)_{aa}\\equiv1\\pmod{2^{M+1}\\mathcal O_L}\n\\quad(1\\le a\\le d).\n\\quad}                                                        \\tag{4}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n右边与提升的选择无关，故这是有限可核验条件。\u003c/p>\n\u003cp>为描述固定矩阵类，取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\varpi_{-1}=1+\\theta_{-1},\\qquad \\varpi_2=\\theta_2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它们均为素元，并满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>⊕\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsubsup>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>∈\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\mathcal O_\\mu=\\mathbb Z_2\\oplus\\mathbb Z_2\\varpi_\\mu,\\qquad\n\\varpi_\\mu^2\\in2\\mathcal O_\\mu,\\qquad\n\\sigma_\\mu(\\varpi_\\mu)-\\varpi_\\mu=-2\\theta_\\mu.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n设\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Sym\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"bold\">n\u003c/mi>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Alt\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"bold\">n\u003c/mi>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Sym\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"bold\">n\u003c/mi>\u003c/msub>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmtext> \u003c/mtext>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\n\\operatorname{Sym}_{\\mathbf n}\n \u0026amp;=\\{Y\\in M_d(\\mathbb F_2):[Y,E_i]=0,\\ Y^{\\mathsf T}=Y\\},\\\\\n\\operatorname{Alt}_{\\mathbf n}\n \u0026amp;=\\{Y\\in\\operatorname{Sym}_{\\mathbf n}:Y_{aa}=0\\ \\forall a\\}.\n\\end{aligned}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其维数分别为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k+d\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这里特征 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">Alt\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{Alt}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 指对称且对角为零。\u003c/p>\n\u003cp>固定点的具体矩阵类为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>Y\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>Y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Alt\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"bold\">n\u003c/mi>\u003c/msub>\u003cmo fence=\"true\">}\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>Y\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>Y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Sym\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"bold\">n\u003c/mi>\u003c/msub>\u003cmo fence=\"true\">}\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(5)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\n\\begin{aligned}\n\\mathscr R_{K_\\mu,M}(A)^{\\sigma_\\mu}\n \u0026amp;=\\left\\{X+2^{M-1}\\varpi_\\mu Y:\n       X\\in\\mathscr R_{F,M}(A),\\\n       Y\\in\\operatorname{Alt}_{\\mathbf n}\\right\\},\\\\\n\\mathscr C_{K_\\mu,M}(A)^{\\sigma_\\mu}\n \u0026amp;=\\left\\{X+2^{M-1}\\varpi_\\mu Y:\n       X\\in\\mathscr C_{F,M}(A),\\\n       Y\\in\\operatorname{Sym}_{\\mathbf n}\\right\\}.\n\\end{aligned}}                                                \\tag{5}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n加法在模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\\mathcal O_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中进行，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 任取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0,1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 提升；两式中的参数表示都唯一。特别地，扩域集合中的基域矩阵类恰为基域相应集合：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∩\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∩\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(6)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\n\\mathscr R_{K_\\mu,M}(A)\\cap M_d(\\mathbb Z_2/2^M)\n \u0026amp;=\\mathscr R_{F,M}(A),\\\\\n\\mathscr C_{K_\\mu,M}(A)\\cap M_d(\\mathbb Z_2/2^M)\n \u0026amp;=\\mathscr C_{F,M}(A).\n\\end{aligned}                                                 \\tag{6}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>固定点数及轨道数如下：\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center center\" columnlines=\"solid solid\" columnspacing=\"1em\" rowlines=\"solid none none\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmtext>集合\u003c/mtext>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmtext>固定点数\u003c/mtext>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmtext> 轨道数\u003c/mtext>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>χ\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmfrac>\u003cmi>χ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>χ\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>d\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmfrac>\u003cmi>χ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>k\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>d\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>d\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>r\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(7)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{array}{c|c|c}\n\\text{集合}\u0026amp;\\text{固定点数}\u0026amp;\\langle\\sigma_\\mu\\rangle\\text{ 轨道数}\\\\ \\hline\n\\mathscr R_{K_\\mu,M}\n\u0026amp;\\chi\\,2^{kM+r}\n\u0026amp;\\displaystyle\\frac{\\chi}{2}\n \\left(2^{2k(M-1)+r}+2^{kM+r}\\right)\\\\[2mm]\n\\mathscr C_{K_\\mu,2}\n\u0026amp;2^{2(k+d)}\n\u0026amp;2^{2(k+d)}\\\\[1mm]\n\\mathscr C_{K_\\mu,M},\\ M\\ge3\n\u0026amp;\\chi\\,2^{kM+2d+r}\n\u0026amp;\\displaystyle\\frac{\\chi}{2}\n \\left(2^{2k(M-1)+2d+r}+2^{kM+2d+r}\\right)\n\\end{array}                                                   \\tag{7}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n两种扩张的这些数字相同。精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时作用均平凡；若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>k\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，各精度上的作用都平凡。\u003c/p>\n\u003cp>对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，约化像和非空纤维大小为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center center\" columnlines=\"solid solid\" columnspacing=\"1em\" rowlines=\"solid none none none\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmtext>约化映射\u003c/mtext>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmtext>像\u003c/mtext>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmtext>每个非空纤维的大小\u003c/mtext>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo>⟶\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmo>⟶\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>k\u003c/mi>\u003c/mrow>\u003c/msup>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003cmo>⟶\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msubsup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>k\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>d\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(8)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{array}{c|c|c}\n\\text{约化映射}\u0026amp;\\text{像}\u0026amp;\\text{每个非空纤维的大小}\\\\ \\hline\n\\mathscr R_{L,M+1}\\longrightarrow\\mathscr R_{L,M}\n\u0026amp;\\mathscr R_{L,M}\u0026amp;2^{e_Lk}\\\\\n\\mathscr C_{L,M+1}\\longrightarrow\\mathscr C_{L,M}\n\u0026amp;\\mathscr R_{L,M}\u0026amp;2^{e_L(k+d)}\\\\\n\\mathscr R_{K_\\mu,M+1}^{\\sigma_\\mu}\n \\longrightarrow\\mathscr R_{K_\\mu,M}^{\\sigma_\\mu}\n\u0026amp;\\mathscr R_{F,M}\u0026amp;2^{2k}\\\\\n\\mathscr C_{K_\\mu,M+1}^{\\sigma_\\mu}\n \\longrightarrow\\mathscr C_{K_\\mu,M}^{\\sigma_\\mu}\n\u0026amp;\\mathscr R_{F,M}\u0026amp;2^{2(k+d)}\n\\end{array}                                                   \\tag{8}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n像为空时，自然没有非空纤维。\u003c/p>\n\u003cp>在任一个固定点集中，下述两种要求都恰好选出子集 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：\u003c/p>\n\u003cul>\n\u003cli>能提升为一个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>-固定的真正解；\u003c/li>\n\u003cli>能成为一条逐层相容的固定矩阵类序列的精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 分量。\u003c/li>\n\u003c/ul>\n\u003cp>在式 (5) 中，对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 这等价于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 这等价于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\in\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。事实上\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmunder>\u003cmrow>\u003cmi mathvariant=\"normal\">\u003cmunder accentunder=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">l\u003c/mi>\u003cmi mathvariant=\"normal\">i\u003c/mi>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003c/mrow>\u003cmo stretchy=\"true\">←\u003c/mo>\u003c/munder>\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>M\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi mathvariant=\"normal\">\u003cmunder accentunder=\"true\">\u003cmrow>\u003cmi mathvariant=\"normal\">l\u003c/mi>\u003cmi mathvariant=\"normal\">i\u003c/mi>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003c/mrow>\u003cmo stretchy=\"true\">←\u003c/mo>\u003c/munder>\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi>M\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(9)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\mathscr S_{K_\\mu}(A)^{\\sigma_\\mu}=\\mathscr S_F(A),\\qquad\n\\varprojlim_M\\mathscr R_{K_\\mu,M}(A)^{\\sigma_\\mu}\n=\\varprojlim_M\\mathscr C_{K_\\mu,M}(A)^{\\sigma_\\mu}\n=\\mathscr S_F(A).                                             \\tag{9}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>第 3 问的答案为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi>N\u003c/mi>\u003cmi>max\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmtext>至少有一个 \u003c/mtext>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmn>2.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(10)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\nN_{\\max}=\n\\begin{cases}\nM,\u0026amp;n_1=\\cdots=n_r=1,\\\\\nM-1,\u0026amp;\\text{至少有一个 }n_i\\ge2.\n\\end{cases}}                                                  \\tag{10}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对题设中给定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A,U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，写唯一的逐条目分解\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>P\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>Q\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>P\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>Q\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nU=P+\\varpi_\\mu Q,\\qquad P,Q\\in M_d(\\mathbb Z_2).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmtext>能取 \u003c/mtext>\u003cmi>N\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>M\u003c/mi>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>Q\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>U\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmtext> 是基域矩阵类\u003c/mtext>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(11)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n\\text{能取 }N=M\n\\iff Q\\in2^M M_d(\\mathbb Z_2)\n\\iff U\\bmod2^M\\mathcal O_\\mu\n      \\text{ 是基域矩阵类}.\n\\quad}                                                       \\tag{11}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n固定假设本身等价于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Q\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Q\\in2^{M-1}M_d(\\mathbb Z_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>下面证明所有断言。\u003c/p>\n\u003cp>先从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 构造正交分块。对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，从 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 出发迭代\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>⟼\u003c/mo>\u003cmn>3\u003c/mn>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmn>3\u003c/mn>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nT\\longmapsto3T^2-2T^3.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsubsup>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i^2-A_i\\equiv0\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，每次迭代把幂等误差的整除精度至少加倍，故收敛到对称幂等矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nP_i\\equiv E_i\\pmod2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 彼此交换，并与所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 交换。若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">i\\ne j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_iP_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为零的幂等矩阵，因而为零；同理\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>i\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>i\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(12)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nP_iP_j=0\\quad(i\\ne j),\\qquad \\sum_iP_i=I_d.                    \\tag{12}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这里用到的简单事实是：若幂等矩阵属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2M_d(\\mathbb Z_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，反复取平方便知它属于任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^mM_d(\\mathbb Z_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">im\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_i=\\operatorname{im}P_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。坐标投影 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>→\u003c/mo>\u003cmsubsup>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msubsup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_i\\to\\mathbb Z_2^{I_i}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是同构，故可选唯一图基矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使其 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">I_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 行块为单位矩阵。于是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsup>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>B\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nB=(B_1,\\ldots,B_r)\\equiv I_d\\pmod2,\\qquad\nB^{\\mathsf T}B=\\operatorname{diag}(G_1,\\ldots,G_r),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n且若\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsubsup>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>:\u003c/mo>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nZ_i=\\frac12B_i[I_i^c,:],\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmsubsup>\u003cmi>Z\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(13)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nG_i=I_{n_i}+4Z_i^{\\mathsf T}Z_i.                              \\tag{13}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>真正解和有限层解都必须沿这些 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 分块。具体地，在所考虑的整数环或其模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 商环中，对满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\\equiv I\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U^{\\mathsf T}U=I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi>U\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>j\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>U\u003c/mi>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi mathvariant=\"normal\">∀\u003c/mi>\u003cmi>i\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(14)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n[U^{\\mathsf T}A_iU,E_j]=0\\quad(\\forall i,j)\n\\iff\nP_iU=UE_i\\quad(\\forall i).                                   \\tag{14}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n证明正向时，将幂等提升迭代施于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>U\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U^{-1}A_iU\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。它是块对角矩阵，其第 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>j\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 块模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\delta_{ij}I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；相应幂等矩阵必为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>j\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>I\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\delta_{ij}I\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。反向由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 与所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>j\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_j\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 交换立即得到。\u003c/p>\n\u003cp>因此，分块条件等价于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nU=B\\operatorname{diag}(T_1,\\ldots,T_r),\\qquad T_i\\equiv I\\pmod2,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而正交条件等价于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsubsup>\u003cmi>T\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmsub>\u003cmi>n\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(15)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nT_i^{\\mathsf T}G_iT_i=I_{n_i}.                                \\tag{15}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这些等价关系也全部适用于有限层。\u003c/p>\n\u003cp>需要一个保精度的提升事实。设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为本题三个整数环之一，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">m\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，且对称矩阵 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmn>1\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH\\equiv I\\pmod{2^m},\\qquad H_{aa}\\equiv1\\pmod{2^{m+1}}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n则存在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T\\equiv I\\pmod{2^m}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>H\u003c/mi>\u003cmi>T\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(16)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nT^{\\mathsf T}HT=I.                                           \\tag{16}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n确实，按顺序作 Gram–Schmidt 正交化，所有消元系数都属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^m\\mathcal O\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，范数变化属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{2m}\\mathcal O\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。所得正交基的范数均在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1+2^{m+1}\\mathcal O\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中。每个这样的单位都有唯一的平方根属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1+2^m\\mathcal O\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：写平方根为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>m\u003c/mi>\u003c/msup>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1+2^mx\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，只需解\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nx+2^{m-1}x^2=a,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>↦\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>m\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\\mapsto a-2^{m-1}x^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在完备环 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上为严格压缩映射。缩放各基向量即得 (16)。\u003c/p>\n\u003cp>由此可证明 (4)。首先，将提升 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 改为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi>Z\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V+2^MZ\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，第 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 列范数的变化为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>v\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">⟨\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>z\u003c/mi>\u003cmi>a\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">⟩\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2^{M+1}\\langle v_a,z_a\\rangle+\n2^{2M}\\langle z_a,z_a\\rangle,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{M+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不变，必要性也显然。反过来，由 (14) 选取形如 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\\operatorname{diag}(T_i)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的提升。其 Gram 矩阵已经块对角；每块满足 (16) 的假设，故可在不改变模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 类的前提下变为真正解。\u003c/p>\n\u003cp>现在验证有限可行性判准。写 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i=E_i+2D_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。第一次幂等提升给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nP_i\\equiv E_i+2(E_iD_i+D_iE_i)\\pmod4.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此，图基的非本块部分满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsubsup>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msubsup>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nZ_i\\equiv D_i[I_i^c,I_i]\\pmod2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>γ\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsubsup>\u003cmi>Z\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>Z\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\gamma_{ia}=(Z_i^{\\mathsf T}Z_i)_{aa}\\pmod2\n\\quad(a\\in I_i),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n便有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>γ\u003c/mi>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(17)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\sum_{a\\in I_i}\\gamma_{ia}=\\delta_i.                           \\tag{17}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>考虑一块 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>4\u003c/mn>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G=I+4H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb Z_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上。令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>T\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T=I+2X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 (16)，存在所需真正等距变换，当且仅当可选 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\bmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsup>\u003cmi>X\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>b\u003c/mi>\u003c/munder>\u003cmsubsup>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>于 \u003c/mtext>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(18)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nX^{\\mathsf T}=X,\\qquad\nH_{aa}+X_{aa}+\\sum_bX_{ba}^2=0\n\\quad\\text{于 }\\mathcal O/2\\mathcal O.                         \\tag{18}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n第一条使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>T\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>G\u003c/mi>\u003cmi>T\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T^{\\mathsf T}GT\\equiv I\\pmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，第二条正是对角范数模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>8\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">8\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的条件。\u003c/p>\n\u003cp>在基域上，(18) 化为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(19)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nH_{aa}+\\sum_{b\\ne a}X_{ab}=0\\pmod2.                           \\tag{19}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对称零对角矩阵的行和向量恰为总和为零的向量。因此可解当且仅当\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmi>a\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\sum_aH_{aa}=0\\pmod2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这是完全显式的：若秩为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX_{a,n}=X_{n,a}=H_{aa}\\pmod2\\quad(a\u0026lt;n),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其余非对角位置取零，对角取零；总和条件保证最后一行也正确。秩为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时直接取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>在两个扩张上，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>≃\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>ϖ\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsubsup>\u003cmover accent=\"true\">\u003cmi>ϖ\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>μ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\mathcal O_\\mu/2\\mathcal O_\\mu\n \\simeq\\mathbb F_2[\\bar\\varpi_\\mu]/(\\bar\\varpi_\\mu^2).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n写 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>ϖ\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X=A+\\bar\\varpi_\\mu B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 (18) 化为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>H\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmunder>\u003cmo>∑\u003c/mo>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>b\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>ϖ\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>B\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nH_{aa}+\\sum_{b\\ne a}A_{ab}+\\bar\\varpi_\\mu B_{aa}=0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其常数项仍强制同一个总和条件。结合 (17)，便证明了 (2)，并给出了先求模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 近似、再应用 (16) 的实际构造。\u003c/p>\n\u003cp>接下来计数。可行时固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>W\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">W\\in\\mathscr S_F(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 (14)，所有真正解唯一写成\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmi>W\u003c/mi>\u003cmi mathvariant=\"normal\">diag\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>r\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsubsup>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>V\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(20)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nW\\operatorname{diag}(V_1,\\ldots,V_r),\\qquad\nV_i^{\\mathsf T}V_i=I,\\quad V_i\\equiv I\\pmod2.                  \\tag{20}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n有限层也相应归结为各块正交群。即使不可行，在精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 仍可用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\\bmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 作同样归结，因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>G\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G_i\\equiv I\\pmod4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>对秩 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的单块，记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmfrac linethickness=\"0px\">\u003cmi>n\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">k_n=\\binom n2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>e\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">e=e_L\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>4\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">4\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时写\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmi>X\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nV=I+2X.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n有限层正交条件恰为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O_L/2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上对称，故候选数为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>e\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(21)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n2^{e(k_n+n)}.                                                \\tag{21}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n真正解的约化还须满足 (18) 中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>H\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">H=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的条件。在基域上，非对角部分的行和为零，约束秩为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，对角部分自由，所以数目为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2^{n+k_n-(n-1)}=2^{k_n+1}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n扩域上写 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo>+\u003c/mo>\u003cmover accent=\"true\">\u003cmi>ϖ\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X=A+\\bar\\varpi B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>A\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 有同样条件，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>B\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">B\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的对角为零、非对角自由，数目为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2^{2k_n+1}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n统一为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>e\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(22)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n2^{e k_n+1}.                                                 \\tag{22}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>从精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 到 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，约化到单位矩阵的类写成\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi>X\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>X\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>L\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nI+2^MX,\\qquad X\\in M_n(\\mathcal O_L/2).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n有限层正交只要求 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对称，故核大小为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>e\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmi>n\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{e(k_n+n)}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。真正解约化的额外范数条件为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>X\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX_{aa}=0,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故其核大小为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>e\u003c/mi>\u003cmsub>\u003cmi>k\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^{e k_n}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>另外，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,M+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的约化像恰为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{L,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>：源中的正交条件已经给出目标的额外一位对角范数条件，反向则由真正解直接提升。于是 (21)、(22) 和这些核大小给出 (3)，也证明 (8) 的前两行，包括不可行情形。\u003c/p>\n\u003cp>现在证明固定点公式。任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathcal O_\\mu/2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中的元素写成 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a+b\\varpi_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 后，固定条件为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>b\u003c/mi>\u003cmsub>\u003cmi>θ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>b\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n2b\\theta_\\mu\\in2^M\\mathcal O_\\mu\n\\iff b\\in2^{M-1}\\mathbb Z_2.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此任意固定矩阵类唯一写为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>t\u003c/mi>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>t\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nV=X+tY,\\qquad t=2^{M-1}\\varpi_\\mu,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为基域矩阵类，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y\\in M_d(\\mathbb F_2)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。注意对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsup>\u003cmi>t\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>⊆\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(23)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nt^2\\in2^{2M-1}\\mathcal O_\\mu\n   \\subseteq2^{M+1}\\mathcal O_\\mu.                            \\tag{23}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>将 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>t\u003c/mi>\u003cmi>Y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V=X+tY\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 代入正交及分块条件。由常数部分得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\in\\mathscr C_{F,M}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varpi_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 部分，并使用\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>I\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\\equiv I\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"0.4444em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>2\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\\equiv E_i\\pmod2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，得到\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>Y\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">]\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nY^{\\mathsf T}=Y,\\qquad [Y,E_i]=0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n反向展开也立即成立，所以得到 (5) 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 公式。\u003c/p>\n\u003cp>对第 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 列范数，利用 (23)，额外一位条件为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmfrac>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsup>\u003cmi>X\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msup>\u003cmi>X\u003c/mi>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mfrac>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"1em\"/>\u003cmtext>于 \u003c/mtext>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\frac{(X^{\\mathsf T}X)_{aa}-1}{2^M}\n  +\\varpi_\\mu Y_{aa}=0\n\\quad\\text{于 }\\mathcal O_\\mu/2\\mathcal O_\\mu.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>ϖ\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1,\\bar\\varpi_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">F\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb F_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上线性无关，这等价于\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>Y\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX\\in\\mathscr R_{F,M}(A),\\qquad Y_{aa}=0.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n从而得到 (5) 的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 公式。唯一性同时证明 (6)。固定点数由维数得到，轨道数由\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"normal\">#\u003c/mi>\u003cmtext>轨道\u003c/mtext>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmrow>\u003cmi mathvariant=\"normal\">#\u003c/mi>\u003cmtext>元素\u003c/mtext>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">#\u003c/mi>\u003cmtext>固定点\u003c/mtext>\u003c/mrow>\u003cmn>2\u003c/mn>\u003c/mfrac>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\#\\text{轨道}=\\frac{\\#\\text{元素}+\\#\\text{固定点}}2\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n得到，故 (7) 成立。\u003c/p>\n\u003cp>固定点在精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的表示为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nX+2^M\\varpi_\\mu Y,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n约化后是基域矩阵类。对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，它属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由已证明的约化像结论，它仍属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R_{F,M}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。反向每个基域真正解都提供固定提升。\u003c/p>\n\u003cp>而且，一个扩域矩阵类若约化到某个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>W\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">W\\in\\mathscr S_F(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 类，它在精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M+1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可写成\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>W\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmi>Z\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nW+2^MZ.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>Z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi>Z\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>M\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\sigma_\\mu(Z)-Z\\in2M_d(\\mathcal O_\\mu)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，这样的类自动固定。因此这些固定纤维就是完整扩域纤维，得到 (8) 后两行。\u003c/p>\n\u003cp>真正固定解逐条目属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"double-struck\">Z\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb Z_2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，所以正是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr S_F(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。相容固定序列取完备极限后也是基域真正解；反向基域真正解给出相容序列。这证明 (9) 及其关于精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 分量的刻画。\u003c/p>\n\u003cp>对下降问题，给定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">U\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 类属于固定的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故由 (5) 唯一写成\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmtext> \u003c/mtext>\u003cmo lspace=\"0.22em\" rspace=\"0.22em\">\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmi>X\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>Y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>X\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmi>Y\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Alt\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"bold\">n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nU\\bmod2^M=X+2^{M-1}\\varpi_\\mu Y,\\qquad\nX\\in\\mathscr R_{F,M}(A),\\quad Y\\in\\operatorname{Alt}_{\\mathbf n}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n选 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>W\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">W\\in\\mathscr S_F(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 提升 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>X\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">X\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，便有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>U\u003c/mi>\u003cmo>≡\u003c/mo>\u003cmi>W\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nU\\equiv W\\pmod{2^{M-1}\\mathcal O_\\mu}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n同精度下降当且仅当 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>Y\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">Y=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，也即 (11)。\u003c/p>\n\u003cp>若每块秩均为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">Alt\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"bold\">n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\operatorname{Alt}_{\\mathbf n}=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。更强地，由 (20)，每块真正正交群只有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo>±\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\{\\pm1\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\mathscr S_{K_\\mu}(A)=\\mathscr S_F(A).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n这证明 (10) 中允许精确下降的情形。\u003c/p>\n\u003cp>只要有一块秩至少为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，下面给出对两种扩张和所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 统一有效的最优性例子。取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i=E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在该块内选两个坐标，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>J\u003c/mi>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nJ=\\begin{pmatrix}0\u0026amp;1\\\\-1\u0026amp;0\\end{pmatrix},\\qquad\na_M=2^{M-2}\\varpi_\\mu,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并在这两个坐标上取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmi>J\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>I\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmi>J\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmfrac>\u003cmn>1\u003c/mn>\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>+\u003c/mo>\u003cmsubsup>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003c/mfrac>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsubsup>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003cmsub>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmsubsup>\u003cmi>a\u003c/mi>\u003cmi>M\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msubsup>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(24)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nT_M=(I+a_MJ)(I-a_MJ)^{-1}\n=\\frac1{1+a_M^2}\n \\begin{pmatrix}1-a_M^2\u0026amp;2a_M\\\\-2a_M\u0026amp;1-a_M^2\\end{pmatrix}.        \\tag{24}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其余坐标取单位矩阵。分母为单位，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">T_M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 真正正交，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmsub>\u003cmi>T\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>≡\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmi>J\u003c/mi>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi mathvariant=\"script\">O\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(25)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\nT_M\\equiv I_2+2^{M-1}\\varpi_\\mu J\n       \\pmod{2^M\\mathcal O_\\mu}.                              \\tag{25}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以它属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">S\u003c/mi>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr S_{K_\\mu}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其模 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2^M\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 类固定，却不是基域矩阵类，无法同精度下降。这证明 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的最优性。它也给出不能提升为固定真正解、不能成为相容固定序列分量的固定 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 类。将参数改为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M-1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，还得到精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下的非固定真正解约化：其非对角位置的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varpi_\\mu\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 系数赋值恰为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M-2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>最后列出其余否定现象的实际例子。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>r\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，选两个不同块中的坐标，在其二维子空间上取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA_1=\\begin{pmatrix}1\u0026amp;2\\\\2\u0026amp;0\\end{pmatrix},\\qquad\nA_2=I_2-A_1,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其余坐标按原投影补齐，其余 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 取相应标准投影。这是合法输入，且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>δ\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\delta_1=\\delta_2=1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故三个域上均无真正解。不过\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>U\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>2\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar U=\\begin{pmatrix}1\u0026amp;2\\\\2\u0026amp;1\\end{pmatrix}\\pmod4\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n补上其他单位坐标后属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>L\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{L,2}(A)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；其列范数为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>5\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">5\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，不能提升为真正解。\u003c/p>\n\u003cp>对任意块秩、任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>E\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_i=E_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，任选坐标 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nD_M=I_d+2^{M-1}\\varpi_\\mu e_{aa}\\pmod{2^M}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmsub>\u003cmi>K\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>A\u003c/mi>\u003cmsup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>σ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{K_\\mu,M}(A)^{\\sigma_\\mu}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，但\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsubsup>\u003cmi>D\u003c/mi>\u003cmi>M\u003c/mi>\u003cmi mathvariant=\"sans-serif\">T\u003c/mi>\u003c/msubsup>\u003cmsub>\u003cmi>D\u003c/mi>\u003cmi>M\u003c/mi>\u003c/msub>\u003cmsub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>≡\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmsub>\u003cmi>ϖ\u003c/mi>\u003cmi>μ\u003c/mi>\u003c/msub>\u003cmo>≢\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n(D_M^{\\mathsf T}D_M)_{aa}-1\n\\equiv2^M\\varpi_\\mu\\not\\equiv0\\pmod{2^{M+1}},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故不属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，不能提升为真正解，也不能进入相容固定序列。\u003c/p>\n\u003cp>基域上，对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>3\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">M\\ge3\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmi>d\u003c/mi>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmi>M\u003c/mi>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msup>\u003cmsub>\u003cmi>e\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmi>a\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmsup>\u003cmn>2\u003c/mn>\u003cmi>M\u003c/mi>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nI_d+2^{M-1}e_{aa}\\pmod{2^M}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n同样属于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi mathvariant=\"script\">C\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∖\u003c/mo>\u003cmsub>\u003cmi mathvariant=\"script\">R\u003c/mi>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>M\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>E\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathscr C_{F,M}(E)\\setminus\\mathscr R_{F,M}(E)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。精度 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 时，只要一块秩至少为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>2\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，在该块取\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>I\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmn>2\u003c/mn>\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>1\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmn>0\u003c/mn>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmspace>\u003c/mspace>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmrow>\u003cmi mathvariant=\"normal\">m\u003c/mi>\u003cmi mathvariant=\"normal\">o\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmspace width=\"0.3333em\"/>\u003cmn>4\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nI_2+2\\begin{pmatrix}0\u0026amp;1\\\\1\u0026amp;0\\end{pmatrix}\\pmod4\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n也有同样性质，因为列范数为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>5\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">5\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这些构造分别实现了表 (8) 中相应约化映射不能覆盖整个目标集合的情形。\u003c/p>\n","source":"assets/content/38b98beaed26bf94c747aa3b2acdedf218121eb4f2f544a0a1594c3f83548953.html"});
